mapper.select:
SELECT * FROM ( SELECT ROWNUM rn, inner.* FROM ( SELECT BD.BRD_NO, BD.BRD_TITL_NM, BD.BRD_CONT, BD.BRD_PBLS_DTM, BD.BRD_VW_CNT, BD.BRD_END_DTM, BD.BRD_DEL_YN, BD.BRD_CTGRY_GRP_CD, BD.BRD_CODE, MEM.MBR_ID, MEM.MBR_CD, C.CODE_NAME AS BRD_CTGRY_NAME FROM BOARD BD LEFT JOIN MEMBER MEM ON BD.MBR_CD = MEM.MBR_CD LEFT JOIN COMMON_CODE C ON C.CODE_GROUP = BD.BRD_CTGRY_GRP_CD AND C.CODE_VALUE = BD.BRD_CODE WHERE BD.BRD_DEL_YN = 'N'
AND (BD.BRD_END_DTM IS NULL OR BD.BRD_END_DTM >= SYSDATE)
AND BD.BRD_CODE = #{detailSearch.brdCode}
ORDER BY BD.BRD_PBLS_DTM DESC ) inner WHERE ROWNUM <= #{lastRecordIndex} ) WHERE rn >= #{firstRecordIndex}

mapper.insert:
SELECT TO_CHAR(SEQ_BRD_NO.NEXTVAL) FROM DUAL
INSERT INTO BOARD ( BRD_NO, BRD_CODE, MBR_CD, BRD_TITL_NM, BRD_CONT, BRD_PBLS_DTM, BRD_VW_CNT, BRD_DEL_YN, BRD_DEL_YN_GRP_CD, BRD_CTGRY_GRP_CD,
BRD_END_DTM
) VALUES ( #{brdNo}, #{brdCode}, #{mbrCd}, #{brdTitlNm}, #{brdCont}, SYSDATE, 0, 'N', #{brdDelYnGrpCd}, #{brdCtgryGrpCd},
#{brdEndDtm}
)
